// Programa por FORMATO: cortos en HORAS_SHORT_UTC (2 al día) y largos en HORAS_LARGO_UTC (1 al día).
// Ecuador UTC-5: 13 = 08:00, 18 = 13:00, 24 = 19:00. Tope de SUBIDAS por día (YouTube cuenta subidas, no publicaciones).
const cfg = $('⚙️ Config').first().json;
const HS = String(cfg.HORAS_SHORT_UTC || '13,24').split(',').map(Number);
const HL = String(cfg.HORAS_LARGO_UTC || '18').split(',').map(Number);
const MAX_SUB = Number(cfg.MAX_SUBIDAS_DIA || 4);
const rows = $input.all().map(i => i.json);
const est = r => { const e = String(r.ESTADO_CORTO || '').toLowerCase().trim(); return e === 'pendiente_youtube' ? 'renderizado' : e; };
const ahora = new Date();
const hoy = ahora.toISOString().slice(0, 10);
const subidasHoy = rows.filter(r => String(r.SUBIDO_EL || '').slice(0, 10) === hoy).length;
const fechas = rows.map(r => new Date(r.PUBLICAR_EL || '')).filter(d => !isNaN(d));
const programados = fechas.filter(d => d > ahora).length;
const ocupado = c => fechas.some(f => Math.abs(f.getTime() - c.getTime()) < 2 * 3600 * 1000);
const slotPara = horas => {
  for (let dia = 0; dia < 1200; dia++) for (const h of horas) {
    const c = new Date(Date.UTC(ahora.getUTCFullYear(), ahora.getUTCMonth(), ahora.getUTCDate() + dia, h));
    if (c.getTime() - ahora.getTime() < 3 * 3600 * 1000 || ocupado(c)) continue;
    return c;
  }
  return null;
};
const formatoDe = r => {
  let formato = 'short', subtema = String((r && r.SUBTEMAS) || '');
  const fCol = String((r && r.FORMATO) || '').toLowerCase().trim();
  if (['short', 'medio', 'masterclass'].includes(fCol)) {
    formato = fCol;
    if (subtema.includes('::')) subtema = subtema.split('::').slice(1).join('::').trim();
  } else if (subtema.includes('::')) {
    const f = subtema.split('::')[0].trim().toLowerCase();
    if (['short', 'medio', 'masterclass'].includes(f)) { formato = f; subtema = subtema.split('::').slice(1).join('::').trim(); }
  }
  return { formato, subtema };
};
const disponibles = rows.filter(r => ['pendiente', 'procesando', 'renderizado'].includes(est(r)) && String(r.KEYWORD_PRINCIPAL || '').trim());
let elegido = null;
if (programados < Number(cfg.MAX_COLA)) {
  const listoParaSubir = r => { const t = new Date(r.YT_REINTENTO || 0).getTime(); return isNaN(t) || ahora.getTime() - t > 4 * 3600 * 1000; };
  const fechaDe = r => { const t = new Date(r.PUBLICAR_EL || '').getTime(); return isNaN(t) ? 9e15 : t; };
  const renderizados = disponibles.filter(r => est(r) === 'renderizado' && r.VIDEO_URL_CORTO).sort((a, b) => fechaDe(a) - fechaDe(b));
  // Sube a YouTube solo hasta el tope diario; el resto del tiempo SIGUE FABRICANDO sin parar (cada video ya nace con su fecha)
  const paraSubir = subidasHoy < MAX_SUB ? renderizados.find(listoParaSubir) : null;
  elegido = paraSubir || disponibles.find(r => est(r) !== 'renderizado') || null;
}
const { formato, subtema } = formatoDe(elegido);
const fFija = elegido && est(elegido) === 'renderizado' ? new Date(elegido.PUBLICAR_EL || '') : null;
const slot = !elegido ? null
  : (fFija && !isNaN(fFija)) ? (fFija.getTime() - ahora.getTime() > 3600 * 1000 ? fFija : new Date(ahora.getTime() + 3600 * 1000))
  : slotPara(formato === 'short' ? HS : HL);
const maxId = Math.max(0, ...rows.map(r => parseInt(String(r.ID || '').replace(/\D/g, ''), 10) || 0));
const publicados = rows.filter(r => r.YOUTUBE_ID).map(r => ({ id: r.YOUTUBE_ID, tema: r.KEYWORD_PRINCIPAL }));
return [{ json: {
  headers: Object.keys(rows[0] || {}).filter(k => !/^row[_]/i.test(k)),
  hay_tema: !!elegido,
  ya_renderizado: !!(elegido && est(elegido) === 'renderizado' && elegido.VIDEO_URL_CORTO),
  necesita_temas: disponibles.filter(r => est(r) === 'pendiente').length < 50,
  ID: elegido ? elegido.ID : '',
  _keyword: elegido ? String(elegido.KEYWORD_PRINCIPAL).trim() : '',
  _subtema: subtema,
  _formato: formato,
  VIDEO_URL_CORTO: elegido ? (elegido.VIDEO_URL_CORTO || '') : '',
  TITULO_CORTO: elegido ? (elegido.TITULO_CORTO || '') : '',
  DESC_CORTO: elegido ? (elegido.DESC_CORTO || '') : '',
  TAGS_CORTO: elegido ? (elegido.TAGS_CORTO || '') : '',
  HASHTAGS_CORTO: elegido ? (elegido.HASHTAGS_CORTO || '') : '',
  existentes: rows.map(r => String(r.KEYWORD_PRINCIPAL || '').trim()).filter(Boolean),
  publicados_ids: publicados.map(p => p.id).slice(-50).join(','),
  publicados,
  next_id: maxId + 1,
  slot_iso: slot ? slot.toISOString() : '',
  programados,
  subidas_hoy: subidasHoy
}}];

const plan = $('🗓️ Planificar (tema + horario)').first().json;
const items = ($input.first().json.items || []);
const pts = {};
for (const it of items) { const s = it.statistics || {}; pts[it.id] = Number(s.viewCount || 0) + 3 * Number(s.likeCount || 0) + 5 * Number(s.commentCount || 0); }
const top = plan.publicados.filter(p => pts[p.id] !== undefined).sort((a, b) => pts[b.id] - pts[a.id]).slice(0, 5).map(p => p.tema + ' (' + pts[p.id] + ' pts)');
return [{ json: { top: top.length ? top.join(' | ') : 'todavía no hay datos suficientes' } }];

const plan = $('🗓️ Planificar (tema + horario)').first().json;
const d = $input.first().json;
let lista = d.temas || (typeof d.text === 'string' ? (JSON.parse(d.text).temas || []) : ((d.text && d.text.temas) || []));
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
const STOP = new Set(['mi','tu','el','la','los','las','de','del','en','y','que','por','para','con','un','una','se','es','a','como','cuando','huron','hurones','hacer','sintomas','causas']);
const tokens = s => new Set(norm(s).split(' ').filter(w => w.length > 2 && !STOP.has(w)));
const parecido = (a, b) => { const A = tokens(a), B = tokens(b); if (!A.size || !B.size) return 0; let i = 0; for (const x of A) if (B.has(x)) i++; return i / Math.min(A.size, B.size); };
const usados = [...plan.existentes];
const headers = Array.isArray(plan.headers) && plan.headers.length ? plan.headers : ['ID','ESTADO','KEYWORD_PRINCIPAL','CIUDAD','SUBTEMAS','ESTADO_CORTO','FORMATO'];
const out = [];
let id = plan.next_id;
for (const t of lista) {
  const kw = String(t.keyword || '').trim();
  const fmt = ['short','medio','masterclass'].includes(String(t.formato || '').toLowerCase().trim()) ? String(t.formato).toLowerCase().trim() : 'short';
  if (!kw) continue;
  if (usados.some(u => norm(u) === norm(kw) || parecido(u, kw) >= 0.8)) continue;
  usados.push(kw);
  const fila = { ID: 'H' + String(id++).padStart(3, '0'), ESTADO: 'pendiente', KEYWORD_PRINCIPAL: kw, CIUDAD: 'Ventanas, Los Ríos', SUBTEMAS: fmt + ' :: ' + String(t.subtemas || ''), FORMATO: fmt, ESTADO_CORTO: 'pendiente' };
  out.push({ json: Object.fromEntries(Object.entries(fila).filter(([k]) => headers.includes(k))) });
}
return out;

const plan = $('🗓️ Planificar (tema + horario)').first().json;
const cfg = $('⚙️ Config').first().json;
