const cfg = $('⚙️ Config').first().json;
const src = plan.ya_renderizado ? plan : $('✅ Video renderizado').first().json;
const blog = 'https://' + cfg.BLOG_URL;
const esShort = String(plan._formato || 'short') === 'short';
const limpiar = s => String(s || '').replace(/[<>]/g, '');
const titulo = limpiar(String(src.TITULO_CORTO || plan._keyword).slice(0, 85)) + (esShort ? ' #Shorts' : ' | Guía completa');
const cta = esShort
  ? '🔔 SUSCRÍBETE para más guías sobre hurones'
  : '🔔 SUSCRÍBETE y activa la campanita para no perderte las próximas masterclasses sobre hurones';
const DESCRIPCION = ('📖 Guía completa: ' + blog + '\n\n' + limpiar(src.DESC_CORTO) + '\n\n' + cta + '\n💬 Comunidad de WhatsApp del Dr. García: https://chat.whatsapp.com/IkpYnlrPyE8Y2NTyaFB6P\n👨‍⚕️ Dr. Luis Arturo García · Médico Veterinario · Ventanas, Los Ríos, Ecuador\n\n' + limpiar(src.HASHTAGS_CORTO)).slice(0, 4800);
const tags = [];
let total = 0;
for (const t0 of String(src.TAGS_CORTO || '').split(',')) {
  const t = limpiar(t0).trim().slice(0, 60);
  if (!t) continue;
  const costo = t.length + (t.includes(' ') ? 2 : 0) + 1;
  if (total + costo > 380) break;
  tags.push(t); total += costo;
}
return [{ json: { ID: plan.ID, VIDEO_URL_CORTO: src.VIDEO_URL_CORTO, TITULO: titulo, DESCRIPCION, TAGS: tags.join(','), PUBLICAR_EL: plan.slot_iso } }];

const item = $input.first();
if (item.binary && item.binary.data) {
  item.binary.data.mimeType = 'video/mp4';
  item.binary.data.fileName = String(item.json.ID || 'video') + '.mp4';
  item.binary.data.fileExtension = 'mp4';
}
return [item];

const it = $input.first().json;
const prep = $('📤 Preparar subida').first().json;
const e = it.error || {};
const msgAll = (typeof e === 'string' ? e : [e.message, e.description, typeof e.error === 'object' ? (e.error && e.error.message) : e.error].map(x => String(x || '')).join(' | '));
const videoId = it.id || it.uploadId || '';
if (videoId && !it.error) return [{ json: { ruta: 'ok', ID: prep.ID, uploadId: videoId } }];
return [{ json: { ruta: 'error', ID: prep.ID, ESTADO_CORTO: 'renderizado', YT_REINTENTO: new Date().toISOString(), motivo: msgAll.slice(0, 180) } }];

const d = $input.first().json;
let m = d;
if (!m || !m.modulos) { let raw = d.text || d.output || ''; m = typeof raw === 'object' ? raw : JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim()); }
if (!m.modulos || !m.modulos.length) throw new Error('Plan de masterclass sin módulos');
return m.modulos.map((mo, i) => ({ json: { indice: i + 1, modulo: mo } }));

const plan = $('🗓️ Planificar (tema + horario)').first().json;
const metaRaw = $('🤖 Plan masterclass').first().json;
let m = metaRaw;
if (!m || !m.modulos) { let raw = metaRaw.text || metaRaw.output || ''; m = typeof raw === 'object' ? raw : JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim()); }
const escenas = [];
for (const it of $input.all()) {
  let d = it.json;
  if (!d || !d.escenas) { let raw = d.text || d.output || ''; d = typeof raw === 'object' ? raw : JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim()); }
  for (const e of (d.escenas || [])) if (e && e.narracion) escenas.push(e);
}
if (escenas.length < 28) throw new Error('Masterclass incompleta: solo ' + escenas.length + ' escenas');
return [{ json: { titulo_video: String(m.titulo_video || plan._keyword).slice(0, 90), descripcion_seo: m.descripcion_seo || '', palabras_clave: m.palabras_clave || '', hashtags: m.hashtags || '', escenas } }];

const d = $input.first().json;
let g = Array.isArray(d.escenas) ? d : null;
if (!g) { let raw = d.text || d.output || ''; g = typeof raw === 'object' ? raw : JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim()); }
let escenas = (g.escenas || []).filter(e => e && e.narracion);
const contar = arr => arr.reduce((n, e) => n + e.narracion.split(/\s+/).length, 0);
const palabras = contar(escenas);
const plan = $('🗓️ Planificar (tema + horario)').first().json;
const formato = String(plan._formato || 'short');
const RANGOS = { short: [330, 700], medio: [1400, 2400], masterclass: [3200, 5600] };
const r = RANGOS[formato] || RANGOS.short;
if (palabras < r[0] || palabras > r[1]) throw new Error('Guion fuera de rango (' + formato + '): ' + palabras + ' palabras en ' + escenas.length + ' escenas');
return [{ json: { ID: plan.ID, keyword: plan._keyword, formato, titulo_video: String(g.titulo_video || plan._keyword).slice(0, 90),
  descripcion_seo: g.descripcion_seo || '', palabras_clave: g.palabras_clave || '', hashtags: g.hashtags || '', total_palabras: palabras, escenas } }];

const fotos = $input.all();
const escenas = $('✂️ Separar escenas').all();
const plan = $('🗓️ Planificar (tema + horario)').first().json;
const formato = String(plan._formato || 'short');
const vertical = formato === 'short';
const usadas = new Set();
const out = [];
let conFoto = 0;
for (let i = 0; i < escenas.length; i++) {
  const esc = escenas[i].json.escena;
  const photos = (fotos[i] && fotos[i].json && fotos[i].json.photos) || [];
  const p = photos.find(x => !usadas.has(x.id)) || photos[0];
  let url = null;
  if (p) {
    usadas.add(p.id);
    url = vertical
      ? p.src.original + '?auto=compress&cs=tinysrgb&fit=crop&w=1080&h=1920'
      : p.src.original + '?auto=compress&cs=tinysrgb&fit=crop&w=1920&h=1080';
    conFoto++;
  }
  else if (out.length) url = out[out.length - 1].image_url;
  out.push({ text: esc.narracion, image_url: url });
}
if (conFoto === 0) throw new Error('PEXELS no devolvió imágenes (revisa la clave de Pexels)');
for (let i = 0; i < out.length; i++) if (!out[i].image_url) out[i].image_url = out.find(e => e.image_url).image_url;
const g = $('📝 Validar guion').first().json;
const cfg = $('⚙️ Config').first().json;
const tag = g.ID + '-' + Date.now();
const job = { id: g.ID, orientation: vertical ? 'vertical' : 'horizontal', formato, voice: 'es-EC-LuisNeural', blog_url: cfg.BLOG_URL, scenes: out };
return [{ json: { ...g, tag, job_str: JSON.stringify(job) } }];

